import AdBlockCore
import Foundation

/// Shared by the three Safari content blocker extensions (Ads, Privacy,
/// Annoyances). Each extension's Info.plist sets `BlockerCategory` so the
/// handler knows which rule file, generated by the main app, to hand to Safari.
final class ContentBlockerRequestHandler: NSObject, NSExtensionRequestHandling {
    func beginRequest(with context: NSExtensionContext) {
        let rawCategory = Bundle.main.object(forInfoDictionaryKey: "BlockerCategory") as? String
        let category = rawCategory.flatMap(FilterCategory.init(rawValue:)) ?? .ads

        let generated = SharedContainer.blockerListURL(for: category)
        let url: URL
        if FileManager.default.fileExists(atPath: generated.path) {
            url = generated
        } else if let bundled = Bundle.main.url(forResource: "DefaultBlockerList", withExtension: "json") {
            // First launch: the app hasn't downloaded the filter lists yet.
            url = bundled
        } else {
            context.cancelRequest(withError: NSError(domain: "AdBlock.ContentBlocker", code: 1))
            return
        }

        let item = NSExtensionItem()
        if let attachment = NSItemProvider(contentsOf: url) {
            item.attachments = [attachment]
        }
        context.completeRequest(returningItems: [item], completionHandler: nil)
    }
}
